using System.Buffers.Binary;
using System.IO.Compression;
using System.Text;
using System.Text.Json;
using SimplePZMapmaker.Core;
namespace SimplePZMapmaker.Web.Services;

// OSM PBF wire format: https://github.com/openstreetmap/OSM-binary/tree/master/osmpbf.
// Compact bounded node index plus complete segment/ring intersection, not in-box-vertex heuristics.
public static class PbfExtractReader
{
 public sealed record Result(string Data,int OmittedRelations,string? Timestamp,int OmittedWays=0);
 private sealed record Way(long Id,Dictionary<string,string> Tags,long[] Refs);
 private sealed record Member(long Id,string Role);
 private sealed record Relation(long Id,Dictionary<string,string> Tags,List<Member> Members,bool HasNested=false);
 private sealed record Block(byte[] Bytes,List<string> Strings,List<byte[]> Groups,int Granularity,long LatOffset,long LonOffset);
 private const int MaxBlock=32*1024*1024,MaxPoints=250000,MaxObjects=30000;
 public sealed record Budgets(int Nodes=8000000,int Ways=500000,int References=10000000,int GeometryWork=30000000);
 public static Result Read(string path,GeoBounds bounds,CancellationToken token=default,Budgets? budgets=null){try{return ReadData(path,bounds,token,budgets??new());}catch(Exception e) when(e is IOException or InvalidDataException or OverflowException or InvalidOperationException or ArgumentOutOfRangeException){token.ThrowIfCancellationRequested();throw new ArgumentException("Invalid or truncated regional PBF extract.",e);}}
 private static Result ReadData(string path,GeoBounds bounds,CancellationToken token,Budgets budgets){
  ProjectValidator.ValidateBounds(bounds);if(new FileInfo(path).Length>64*1024*1024)throw Fail("The regional extract exceeds 64 MB.");
  Limit(budgets.Nodes,8000000,1);Limit(budgets.Ways,500000,1);Limit(budgets.References,10000000,1);Limit(budgets.GeometryWork,30000000,1);
  var builder=new NodeBuilder(budgets.Nodes);string? timestamp=null;Scan(path,token,(b,kind,bytes)=>{if(kind is 1 or 2)Nodes(b,kind,bytes,builder.Add,token);},value=>timestamp=value);var index=builder.Build(token);
  var allWays=new Dictionary<long,long[]>();var selectedWays=new Dictionary<long,Way>();var relations=new List<Relation>();long totalRefs=0;long tagChars=0;var omittedWays=0;var work=new Geometry(index,bounds,token,budgets.GeometryWork);
  Scan(path,token,(b,kind,bytes)=>{if(kind==3){var way=ReadWay(b,bytes);if(!allWays.TryAdd(way.Id,way.Refs))throw Fail("Duplicate PBF way ID.");Limit(allWays.Count,budgets.Ways);totalRefs+=way.Refs.Length;LimitLong(totalRefs,budgets.References);if(Relevant(way.Tags)){try{if(work.Intersects(way.Refs,IsAreaWay(way.Tags))){selectedWays.Add(way.Id,way);Limit(selectedWays.Count,MaxObjects);tagChars+=way.Tags.Sum(p=>(long)p.Key.Length+p.Value.Length);LimitLong(tagChars,16000000);}}catch(MissingNodesException){omittedWays++;}}}else if(kind==4){var relation=ReadRelation(b,bytes);if(RelevantRelation(relation.Tags)){relations.Add(relation);Limit(relations.Count,50000);totalRefs+=relation.Members.Count;LimitLong(totalRefs,budgets.References);tagChars+=relation.Tags.Sum(p=>(long)p.Key.Length+p.Value.Length);LimitLong(tagChars,16000000);}}});
  var omitted=0;var areaMembers=new HashSet<long>();var selectedRelations=new List<Relation>();foreach(var r in relations){token.ThrowIfCancellationRequested();foreach(var m in r.Members)areaMembers.Add(m.Id);if(r.HasNested||r.Members.Any(m=>!allWays.ContainsKey(m.Id))){omitted++;continue;}
   var outer=Stitch(r.Members.Where(m=>m.Role!="inner").Select(m=>allWays[m.Id]).ToList(),token,work.Account);var inner=Stitch(r.Members.Where(m=>m.Role=="inner").Select(m=>allWays[m.Id]).ToList(),token,work.Account);if(outer is null||inner is null||outer.Count==0){omitted++;continue;}try{if(work.RelationIntersects(outer,inner)){selectedRelations.Add(r);Limit(selectedRelations.Count,MaxObjects);}}catch(MissingNodesException){omitted++;}
  }
  foreach(var id in selectedWays.Values.Where(w=>areaMembers.Contains(w.Id)&&IsAreaWay(w.Tags)).Select(w=>w.Id).ToArray())selectedWays.Remove(id);
  using var output=new MemoryStream();using(var writer=new Utf8JsonWriter(output)){
   writer.WriteStartObject();writer.WriteString("generator","SimplePZMapmaker OSM PBF extract");if(timestamp is not null)writer.WriteString("timestamp",timestamp);writer.WriteStartArray("elements");
   var outputPoints=0;var outputObjects=0;void WriteGeometry(long[] refs){writer.WriteStartArray("geometry");foreach(var id in refs){Limit(++outputPoints,MaxPoints);if(outputPoints%1024==0)token.ThrowIfCancellationRequested();var p=index.Get(id);writer.WriteStartObject();writer.WriteNumber("lat",p.Lat);writer.WriteNumber("lon",p.Lon);writer.WriteEndObject();}writer.WriteEndArray();}
   void Tags(Dictionary<string,string> tags){writer.WriteStartObject("tags");foreach(var pair in tags)writer.WriteString(pair.Key,pair.Value);writer.WriteEndObject();}
   foreach(var w in selectedWays.Values){token.ThrowIfCancellationRequested();Limit(++outputObjects,MaxObjects);writer.WriteStartObject();writer.WriteString("type","way");writer.WriteNumber("id",w.Id);Tags(w.Tags);WriteGeometry(w.Refs);writer.WriteEndObject();Limit((int)output.Length,16_000_000);}
   foreach(var r in selectedRelations){token.ThrowIfCancellationRequested();Limit(++outputObjects,MaxObjects);writer.WriteStartObject();writer.WriteString("type","relation");writer.WriteNumber("id",r.Id);Tags(r.Tags);writer.WriteStartArray("members");foreach(var member in r.Members){writer.WriteStartObject();writer.WriteString("type","way");writer.WriteNumber("ref",member.Id);writer.WriteString("role",member.Role);WriteGeometry(allWays[member.Id]);writer.WriteEndObject();}writer.WriteEndArray();writer.WriteEndObject();Limit((int)output.Length,16_000_000);}writer.WriteEndArray();writer.WriteEndObject();
  }
  Limit((int)output.Length,16_000_000);return new(Encoding.UTF8.GetString(output.ToArray()),omitted,timestamp,omittedWays);
 }
 private static bool Relevant(Dictionary<string,string> tags)=>tags.Keys.Any(k=>k is "highway" or "building" or "natural" or "landuse" or "waterway" or "railway");
 private static bool RelevantRelation(Dictionary<string,string> tags)=>tags.Keys.Any(k=>k is "building" or "natural" or "landuse");
 private static bool IsAreaWay(Dictionary<string,string> tags)=>tags.ContainsKey("building")||tags.ContainsKey("landuse")||tags.GetValueOrDefault("natural") is "water" or "wood" or "sand" or "beach" or "wetland";
 private readonly record struct GeoNode(long Id,double Lat,double Lon);
 private sealed class NodeBuilder(int maximum){
  private readonly List<GeoNode[]> chunks=[];private int count;
  public void Add(long id,double lat,double lon){if(id<=0||!double.IsFinite(lat)||!double.IsFinite(lon)||lat is < -90 or >90||lon is < -180 or >180)throw Fail("Invalid regional extract nodes.");Limit(count+1,maximum);if(count%65536==0)chunks.Add(new GeoNode[Math.Min(65536,maximum-count)]);chunks[^1][count%65536]=new(id,lat,lon);count++;}
  public NodeIndex Build(CancellationToken token){var nodes=new GeoNode[count];var copied=0;foreach(var chunk in chunks){token.ThrowIfCancellationRequested();var length=Math.Min(chunk.Length,count-copied);Array.Copy(chunk,0,nodes,copied,length);copied+=length;}chunks.Clear();var comparisons=0;Array.Sort(nodes,Comparer<GeoNode>.Create((a,b)=>{if((++comparisons&4095)==0)token.ThrowIfCancellationRequested();return a.Id.CompareTo(b.Id);}));for(var i=1;i<nodes.Length;i++){if((i&4095)==0)token.ThrowIfCancellationRequested();if(nodes[i-1].Id==nodes[i].Id)throw Fail("Duplicate PBF node ID.");}return new(nodes);}
 }
 private sealed class NodeIndex(GeoNode[] nodes){
  public GeoNode Get(long id){var lo=0;var hi=nodes.Length-1;while(lo<=hi){var mid=lo+(hi-lo)/2;var value=nodes[mid];if(value.Id==id)return value;if(value.Id<id)lo=mid+1;else hi=mid-1;}throw new MissingNodesException();}
 }
 private sealed class MissingNodesException:ArgumentException{public MissingNodesException():base("The regional extract is missing nodes required for complete geometry."){}}
 private sealed class Geometry(NodeIndex index,GeoBounds box,CancellationToken token,int budget){
  private int work;
  private void Step(){if((++work&1023)==0)token.ThrowIfCancellationRequested();Limit(work,budget);}
  public void Account()=>Step();
  private GeoNode[] Points(long[] refs){Limit(refs.Length,MaxPoints);var points=new GeoNode[refs.Length];for(var i=0;i<refs.Length;i++){Step();points[i]=index.Get(refs[i]);}return points;}
  private bool Boundary(GeoNode[] points){for(var i=1;i<points.Length;i++){Step();if(Segment(points[i-1],points[i]))return true;}return false;}
  public bool Intersects(long[] refs,bool area){var p=Points(refs);if(p.Length<2)return false;if(Boundary(p))return true;return area&&refs.Length>=4&&refs[0]==refs[^1]&&Inside(box.West,box.South,p);}
  public bool RelationIntersects(List<long[]> outer,List<long[]> inner){var outers=outer.Select(Points).ToList();var inners=inner.Select(Points).ToList();if(outers.Any(Boundary)||inners.Any(Boundary))return true;return outers.Any(r=>Inside(box.West,box.South,r))&&!inners.Any(r=>Inside(box.West,box.South,r));}
  private bool Inside(double x,double y,GeoNode[] ring){var inside=false;for(int i=0,j=ring.Length-1;i<ring.Length;j=i++){Step();var a=ring[i];var b=ring[j];if((a.Lat>y)!=(b.Lat>y)&&x<(b.Lon-a.Lon)*(y-a.Lat)/(b.Lat-a.Lat)+a.Lon)inside=!inside;}return inside;}
  private bool Segment(GeoNode a,GeoNode b){var dx=b.Lon-a.Lon;var dy=b.Lat-a.Lat;var enter=0d;var exit=1d;bool Clip(double direction,double distance){if(direction==0)return distance>=0;var t=distance/direction;if(direction<0){if(t>exit)return false;enter=Math.Max(enter,t);}else{if(t<enter)return false;exit=Math.Min(exit,t);}return true;}return Clip(-dx,a.Lon-box.West)&&Clip(dx,box.East-a.Lon)&&Clip(-dy,a.Lat-box.South)&&Clip(dy,box.North-a.Lat);}
 }
 private static List<long[]>? Stitch(List<long[]> segments,CancellationToken token,Action account){
  var used=new bool[segments.Count];var endpoints=new Dictionary<long,List<int>>();void Link(long id,int i){if(!endpoints.TryGetValue(id,out var list))endpoints[id]=list=[];list.Add(i);}for(var i=0;i<segments.Count;i++){token.ThrowIfCancellationRequested();account();if(segments[i].Length<2)return null;Link(segments[i][0],i);Link(segments[i][^1],i);}var rings=new List<long[]>();
  for(var i=0;i<segments.Count;i++){account();if(used[i])continue;used[i]=true;var ring=new List<long>(segments[i]);while(ring[^1]!=ring[0]){token.ThrowIfCancellationRequested();if(!endpoints.TryGetValue(ring[^1],out var choices))return null;var next=-1;foreach(var choice in choices){account();if(!used[choice]){next=choice;break;}}if(next<0)return null;used[next]=true;var segment=segments[next];if(segment[0]==ring[^1])for(var j=1;j<segment.Length;j++){account();ring.Add(segment[j]);}else for(var j=segment.Length-2;j>=0;j--){account();ring.Add(segment[j]);}Limit(ring.Count,MaxPoints);}if(ring.Count<4)return null;rings.Add(ring.ToArray());}return rings;
 }
 private static void LimitLong(long value,long maximum){if(value<0||value>maximum)throw Fail("The regional extract index or geometry processing exceeds the limit.");}
 private static void Scan(string path,CancellationToken token,Action<Block,int,byte[]> visit,Action<string?>? timestamp=null){
  using var stream=File.OpenRead(path);var headerSeen=false;var dataSeen=false;var prefix=new byte[4];
  while(stream.Position<stream.Length){token.ThrowIfCancellationRequested();stream.ReadExactly(prefix);var length=BinaryPrimitives.ReadInt32BigEndian(prefix);Limit(length,65535,1);var header=new byte[length];stream.ReadExactly(header);var fields=Fields(header);var type=Text(One(fields,1));var size=(int)Integer(fields,3);Limit(size,MaxBlock,1);var blob=new byte[size];stream.ReadExactly(blob);var content=Fields(blob);byte[] raw;
   if(content.TryGetValue(1,out var uncompressed))raw=uncompressed.Single().Bytes;else if(content.TryGetValue(3,out var compressed)){var expected=(int)Integer(content,2);Limit(expected,MaxBlock,1);using var zlib=new ZLibStream(new MemoryStream(compressed.Single().Bytes),CompressionMode.Decompress);raw=new byte[expected];zlib.ReadExactly(raw);if(zlib.ReadByte()!=-1)throw Fail("The decompressed block size does not match the header.");}else throw Fail("Unsupported PBF compression; raw or zlib data is required.");Limit(raw.Length,MaxBlock,1);
   if(type=="OSMHeader"){if(headerSeen||dataSeen)throw Fail("Duplicate PBF header.");headerSeen=true;var f=Fields(raw);foreach(var feature in f.GetValueOrDefault(4,[]).Select(Text))if(feature is not("OsmSchema-V0.6" or "DenseNodes"))throw Fail("Unsupported required PBF feature: "+feature);var seconds=Integer(f,32);if(seconds>0)timestamp?.Invoke(DateTimeOffset.FromUnixTimeSeconds(seconds).ToString("O"));}
   else if(type=="OSMData"){if(!headerSeen)throw Fail("Missing PBF header.");dataSeen=true;var f=Fields(raw);var table=Fields(One(f,1));var strings=table.GetValueOrDefault(1,[]).Select(Text).ToList();Limit(strings.Count,100000);var groups=f.GetValueOrDefault(2,[]).Select(v=>v.Bytes).ToList();var granularity=(int)Integer(f,17,100);Limit(granularity,1000000,1);var b=new Block(raw,strings,groups,granularity,Integer(f,19),Integer(f,20));foreach(var group in groups)foreach(var pair in Fields(group))if(pair.Key is >=1 and <=4)foreach(var value in pair.Value)visit(b,pair.Key,value.Bytes);}
  }if(!headerSeen||!dataSeen)throw Fail("The PBF extract contains no data.");
 }
 private static void Nodes(Block b,int kind,byte[] bytes,Action<long,double,double> visit,CancellationToken token){var f=Fields(bytes);double Lat(long v)=>(b.LatOffset+v*(double)b.Granularity)*1e-9;double Lon(long v)=>(b.LonOffset+v*(double)b.Granularity)*1e-9;
  if(kind==1){visit(Signed((ulong)Integer(f,1)),Lat(Signed((ulong)Integer(f,8))),Lon(Signed((ulong)Integer(f,9))));return;}
  var ids=Packed(f,1,true);var lats=Packed(f,8,true);var lons=Packed(f,9,true);if(ids.Length!=lats.Length||ids.Length!=lons.Length)throw Fail("DenseNodes columns have different lengths.");long id=0,lat=0,lon=0;for(var i=0;i<ids.Length;i++){if(i%1024==0)token.ThrowIfCancellationRequested();id=checked(id+ids[i]);lat=checked(lat+lats[i]);lon=checked(lon+lons[i]);var latitude=Lat(lat);var longitude=Lon(lon);if(!double.IsFinite(latitude)||!double.IsFinite(longitude)||latitude is < -90 or >90||longitude is < -180 or >180)throw Fail("Invalid PBF coordinates.");visit(id,latitude,longitude);}
 }
 private static Way ReadWay(Block b,byte[] bytes){var f=Fields(bytes);long id=0;var refs=Packed(f,8,true).Select(v=>id=checked(id+v)).ToArray();Limit(refs.Length,MaxPoints);return new(Integer(f,1),Tags(b,f),refs);}
 private static Relation ReadRelation(Block b,byte[] bytes){var f=Fields(bytes);var tags=Tags(b,f);if(!RelevantRelation(tags))return new(Integer(f,1),tags,[]);var refs=Packed(f,9,true);var roles=Packed(f,8);var types=Packed(f,10);if(refs.Length!=roles.Length||refs.Length!=types.Length)throw Fail("Invalid PBF relation members.");long id=0;var nested=tags.GetValueOrDefault("type")!="multipolygon";var members=new List<Member>();for(var i=0;i<refs.Length;i++){id=checked(id+refs[i]);if(types[i]==1)members.Add(new(id,String(b,roles[i])));else if(types[i]==2)nested=true;}return new(Integer(f,1),tags,members,nested);}
 private static Dictionary<string,string> Tags(Block b,Dictionary<int,List<Field>> f){var keys=Packed(f,2);var values=Packed(f,3);if(keys.Length!=values.Length)throw Fail("PBF tag keys and values have different lengths.");var result=new Dictionary<string,string>();for(var i=0;i<keys.Length;i++)result[String(b,keys[i])]=String(b,values[i]);return result;}
 private static string String(Block b,long id)=>id>=0&&id<b.Strings.Count?b.Strings[(int)id]:throw Fail("The tag index is outside the PBF string table.");
 private sealed record Field(int Wire,ulong Number,byte[] Bytes);
 private static Dictionary<int,List<Field>> Fields(byte[] bytes){var result=new Dictionary<int,List<Field>>();var position=0;while(position<bytes.Length){var tag=Varint(bytes,ref position);var key=(int)(tag>>3);var wire=(int)(tag&7);if(key<1)throw Fail("Invalid protobuf tag.");ulong number=0;byte[] data=[];if(wire==0)number=Varint(bytes,ref position);else if(wire==2){var length=Varint(bytes,ref position);if(length>(ulong)(bytes.Length-position))throw Fail("Truncated protobuf field.");data=bytes.AsSpan(position,(int)length).ToArray();position+=(int)length;}else if(wire is 1 or 5){var length=wire==1?8:4;if(bytes.Length-position<length)throw Fail("Truncated protobuf field.");position+=length;}else throw Fail("Unsupported protobuf wire type.");if(!result.TryGetValue(key,out var list))result[key]=list=[];list.Add(new(wire,number,data));}return result;}
 private static long Integer(Dictionary<int,List<Field>> fields,int key,long fallback=0)=>fields.TryGetValue(key,out var values)&&values.Count==1&&values[0].Wire==0?unchecked((long)values[0].Number):fields.ContainsKey(key)?throw Fail("Invalid PBF integer field."):fallback;
 private static byte[] One(Dictionary<int,List<Field>> fields,int key)=>fields.TryGetValue(key,out var values)&&values.Count==1&&values[0].Wire==2?values[0].Bytes:throw Fail("Missing required PBF field.");
 private static string Text(Field field)=>field.Wire==2?Encoding.UTF8.GetString(field.Bytes):throw Fail("Invalid PBF string.");private static string Text(byte[] bytes)=>Encoding.UTF8.GetString(bytes);
 private static long[] Packed(Dictionary<int,List<Field>> fields,int key,bool signed=false){var result=new List<long>();foreach(var field in fields.GetValueOrDefault(key,[])){if(field.Wire==0)result.Add(signed?Signed(field.Number):unchecked((long)field.Number));else if(field.Wire==2){var position=0;while(position<field.Bytes.Length){var value=Varint(field.Bytes,ref position);result.Add(signed?Signed(value):unchecked((long)value));Limit(result.Count,MaxPoints);}}else throw Fail("Invalid PBF packed field.");}return result.ToArray();}
 private static ulong Varint(byte[] bytes,ref int position){ulong value=0;for(var shift=0;shift<70;shift+=7){if(position>=bytes.Length)throw Fail("Truncated protobuf number.");var b=bytes[position++];if(shift==63&&b>1)throw Fail("Protobuf number overflow.");value|=(ulong)(b&127)<<shift;if((b&128)==0)return value;}throw Fail("Protobuf number is too long.");}
 private static long Signed(ulong value)=>unchecked((long)(value>>1)^-((long)value&1));private static void Limit(int value,int max,int min=0){if(value<min||value>max)throw Fail("Regional extract data exceeds the size limit.");}private static ArgumentException Fail(string text)=>new(text);
}
